import { test, expect } from '@playwright/test';
import { prepareReadOnly, openCalculator, fillInputs, expectResult, SET1, DEVICES } from './calculator.helpers';

test.use({ serviceWorkers: 'block' });

test.describe('Калькулятор — формулы и крайние случаи', () => {
  for (const tag of DEVICES) {
    test(`Кредит = инвестиции → הון עצמי 0 и ROE «—»; кредит больше → минус и предупреждение #80ff63 #d45b2a ${tag} @prod-safe`, async ({ page, context }) => {
      await prepareReadOnly(context);
      await openCalculator(page);
      await fillInputs(page, { ...SET1, loanAmount: '600000' });

      await expectResult(page, 'הון עצמי נדרש', '0 ₪');
      await expectResult(page, 'תשואה שנתית על ההון העצמי', '—');
      await expect(page.getByText('אין הון עצמי').first()).toBeVisible();

      await fillInputs(page, { loanAmount: '700000' });
      await expectResult(page, 'הון עצמי נדרש', '-100,000 ₪');
      await expect(page.getByText(/סכום ההלוואה גבוה מסך ההשקעה/).first()).toBeVisible();
    });
  }
});
